    /**
     * Performs a targeted restore from an NFS backup.
     *
     * @param string $backupPath The path to the backup file.
     * @param string $restorePath The path to restore the backup to.
     * @return bool True if the restore was successful, false otherwise.
     */
    public function performTargetedRestore($backupPath, $restorePath)
    {
        // Check if the backup file exists
        if (!file_exists($backupPath)) {
            return false;
        }

        // Perform the restore
        $command = "cp -r $backupPath $restorePath";
        exec($command, $output, $returnCode);

        // Check if the restore was successful
        return $returnCode === 0;
    }
