def get_recordset_ids(designate_client, dns_domain, records, v4, v6, name):
    recordsets = []
    if v4:
        criterion = {'type': "A"}
        try:
            recordsets += designate_client.recordsets.list(
                dns_domain, criterion=criterion)
        except (d_exc.NotFound, d_exc.Forbidden):
            raise dns_exc.DNSDomainNotFound(dns_domain=dns_domain)
    if v6:
        criterion = {'type': "AAAA"}
        try:
            recordsets += designate_client.recordsets.list(
                dns_domain, criterion=criterion)
        except (d_exc.NotFound, d_exc.Forbidden):
            raise dns_exc.DNSDomainNotFound(dns_domain=dns_domain)

    ids = [rec['id'] for rec in recordsets if any(str(ip) in rec['records'] for ip in records)]
    ips = [str(ip) for rec in recordsets for ip in rec['records']]

    if set(ips) > set(records):
        raise dns_exc.MismatchedRecordSet(dns_name=name)

    return ids
